from __future__ import annotations

import json
import re
from datetime import datetime, timezone
from typing import Any, BinaryIO

import gridfs
from pymongo import MongoClient
from pymongo.errors import PyMongoError

from lfx.custom import Component
from lfx.io import DataInput, IntInput, Output, SecretStrInput, StrInput
from lfx.schema import Data


_JOB_REF_KEYS = ("tenant_id", "job_id", "snapshot_id", "stage", "expected_cursor", "trace_id")
_SECRET_PATTERNS = (
    (
        "PRIVATE_KEY",
        re.compile(r"-----BEGIN (?:RSA |EC |OPENSSH |DSA )?PRIVATE KEY-----", re.IGNORECASE),
    ),
    (
        "BEARER_TOKEN",
        re.compile(r"\bBearer\s+[A-Za-z0-9._~+/=-]{16,}", re.IGNORECASE),
    ),
    (
        "ASSIGNED_CREDENTIAL",
        re.compile(
            r"\b(?:api[_ -]?key|access[_ -]?token|refresh[_ -]?token|client[_ -]?secret|password|passwd)\b"
            r"\s*[:=]\s*[\"']?[A-Za-z0-9._~+/=-]{8,}",
            re.IGNORECASE,
        ),
    ),
    (
        "AWS_ACCESS_KEY",
        re.compile(r"\b(?:AKIA|ASIA)[A-Z0-9]{16}\b"),
    ),
)


def _utc_now() -> datetime:
    return datetime.now(timezone.utc)


def _bounded_int(value: Any, default: int, minimum: int, maximum: int) -> int:
    try:
        number = int(value)
    except (TypeError, ValueError):
        number = default
    return max(minimum, min(maximum, number))


def _secret_value(value: Any) -> str:
    getter = getattr(value, "get_secret_value", None)
    if callable(getter):
        return str(getter()).strip()
    return str(value or "").strip()


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return dict(value)
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return dict(data)
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return {}
        return parsed if isinstance(parsed, dict) else {}
    return {}


def _validate_job_ref(value: Any) -> dict[str, Any]:
    payload = _payload(value)
    result = {key: payload.get(key) for key in _JOB_REF_KEYS}
    for key in ("tenant_id", "job_id", "snapshot_id", "stage", "trace_id"):
        if not isinstance(result[key], str) or not result[key].strip():
            raise ValueError(f"job_ref.{key} is required.")
        result[key] = result[key].strip()
    try:
        result["expected_cursor"] = max(0, int(result["expected_cursor"] or 0))
    except (TypeError, ValueError) as exc:
        raise ValueError("job_ref.expected_cursor must be an integer.") from exc
    return result


def _scan_text(text: str) -> dict[str, int]:
    return {code: len(pattern.findall(text)) for code, pattern in _SECRET_PATTERNS if pattern.search(text)}


def _scan_stream(handle: BinaryIO, chunk_bytes: int, max_bytes: int) -> tuple[dict[str, int], int]:
    counts: dict[str, int] = {}
    total = 0
    tail = ""
    while True:
        chunk = handle.read(chunk_bytes)
        if not chunk:
            break
        total += len(chunk)
        if total > max_bytes:
            raise ValueError("The restricted source exceeds the configured scan limit.")
        current = chunk.decode("utf-8", errors="replace")
        window = tail + current
        window_counts = _scan_text(window)
        tail_counts = _scan_text(tail)
        for code, count in window_counts.items():
            counts[code] = counts.get(code, 0) + max(0, count - tail_counts.get(code, 0))
        tail = window[-512:]
    return counts, total


def _job_ref(source: dict[str, Any], stage: str) -> dict[str, Any]:
    return {
        "tenant_id": source["tenant_id"],
        "job_id": source["job_id"],
        "snapshot_id": source["snapshot_id"],
        "stage": stage,
        "expected_cursor": int(source.get("expected_cursor") or 0),
        "trace_id": source["trace_id"],
    }


def _failure(code: str, message: str, trace_id: str, retryable: bool = False) -> Data:
    return Data(
        data={
            "ok": False,
            "run_id": trace_id,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": code, "message": message, "retryable": retryable, "details": {}},
            "resume": None,
            "trace_id": trace_id,
        }
    )


class CatalogSecretScannerComponent(Component):
    display_name = "Catalog Secret Scanner"
    description = "Scan the restricted catalog source for high-confidence credentials and quarantine matching jobs."
    icon = "ShieldAlert"
    name = "CatalogSecretScanner"

    inputs = [
        DataInput(name="job_ref", display_name="Catalog Ingest Job Reference", required=True),
        SecretStrInput(name="mongodb_uri", display_name="MongoDB URI", required=True),
        StrInput(name="mongodb_database", display_name="MongoDB Database", value="business_work_design", required=True),
        IntInput(name="max_scan_mb", display_name="Maximum Scan Size (MiB)", value=100, advanced=True),
        IntInput(name="scan_chunk_kb", display_name="Scan Chunk Size (KiB)", value=256, advanced=True),
        IntInput(name="connect_timeout_ms", display_name="MongoDB Connect Timeout (ms)", value=5000, advanced=True),
    ]

    outputs = [Output(name="scanned_job_ref", display_name="Scanned Job Reference", method="scan_source", types=["Data"])]

    def scan_source(self) -> Data:
        trace_id = "trace-unassigned"
        try:
            incoming = _validate_job_ref(getattr(self, "job_ref", None))
            trace_id = incoming["trace_id"]
            mongodb_uri = _secret_value(getattr(self, "mongodb_uri", ""))
            database_name = str(getattr(self, "mongodb_database", "") or "").strip()
            if not mongodb_uri or not database_name:
                return _failure("MONGODB_CONFIG_MISSING", "MongoDB configuration is required.", trace_id)

            timeout_ms = _bounded_int(getattr(self, "connect_timeout_ms", 5000), 5000, 1000, 30000)
            chunk_bytes = _bounded_int(getattr(self, "scan_chunk_kb", 256), 256, 64, 1024) * 1024
            max_bytes = _bounded_int(getattr(self, "max_scan_mb", 100), 100, 1, 200) * 1024 * 1024
            client = MongoClient(
                mongodb_uri,
                connectTimeoutMS=timeout_ms,
                serverSelectionTimeoutMS=timeout_ms,
                socketTimeoutMS=max(timeout_ms, 5000),
                retryReads=True,
                retryWrites=True,
            )
            try:
                client.admin.command("ping")
                database = client[database_name]
                jobs = database["catalog_ingest_jobs"]
                query = {
                    "_id": incoming["job_id"],
                    "tenant_id": incoming["tenant_id"],
                    "snapshot_id": incoming["snapshot_id"],
                }
                job = jobs.find_one(query)
                if not job:
                    return _failure("CATALOG_JOB_NOT_FOUND", "The catalog ingest job was not found for this tenant.", trace_id)

                current_stage = str(job.get("stage") or "")
                if current_stage in {"SECRET_SCAN_PASSED", "QUARANTINED_SECRET"}:
                    self.status = f"Secret scan already completed: job_id={incoming['job_id']}, stage={current_stage}"
                    return Data(data=_job_ref(incoming, current_stage))
                if current_stage != "INTAKE_STORED":
                    return _failure("CATALOG_STAGE_CONFLICT", "Secret scan requires an intake-stored job.", trace_id)
                if incoming["stage"] != "INTAKE_STORED" or incoming["expected_cursor"] != 0:
                    return _failure("CATALOG_CURSOR_CONFLICT", "The secret-scan job reference is stale.", trace_id)

                blob_id = job.get("source_blob_id")
                if blob_id is None:
                    return _failure("CATALOG_SOURCE_MISSING", "The restricted catalog source is unavailable.", trace_id)
                bucket = gridfs.GridFS(database, collection="catalog_source_files_blob")
                source = bucket.get(blob_id)
                counts, scanned_bytes = _scan_stream(source, chunk_bytes, max_bytes)
                now = _utc_now()
                quarantined = bool(counts)
                next_stage = "QUARANTINED_SECRET" if quarantined else "SECRET_SCAN_PASSED"
                scan_summary = {
                    "completed": True,
                    "quarantined": quarantined,
                    "match_counts": counts,
                    "scanned_bytes": scanned_bytes,
                    "scanner_version": "catalog-secret-v1",
                    "scanned_at": now,
                }
                update = jobs.update_one(
                    {**query, "stage": "INTAKE_STORED"},
                    {"$set": {"stage": next_stage, "secret_scan": scan_summary, "updated_at": now}},
                )
                if update.modified_count != 1:
                    return _failure("CATALOG_STAGE_CONFLICT", "The ingest job changed while secret scan was running.", trace_id, True)
                database["catalog_source_files"].update_one(
                    {"_id": str(job.get("source_file_id") or incoming["job_id"]), "tenant_id": incoming["tenant_id"]},
                    {"$set": {"status": next_stage, "secret_scan": scan_summary, "updated_at": now}},
                )
                self.status = (
                    f"Catalog source quarantined: job_id={incoming['job_id']}, finding_types={len(counts)}"
                    if quarantined
                    else f"Secret scan passed: job_id={incoming['job_id']}, bytes={scanned_bytes}"
                )
                return Data(data=_job_ref(incoming, next_stage))
            finally:
                client.close()
        except ValueError as exc:
            self.status = "Secret scan rejected by input validation."
            return _failure("SECRET_SCAN_INPUT_INVALID", str(exc), trace_id)
        except (PyMongoError, gridfs.errors.GridFSError, OSError, UnicodeError):
            self.status = "Secret scan could not complete."
            return _failure(
                "SECRET_SCAN_FAILED",
                "The restricted source could not be scanned. The job remains blocked.",
                trace_id,
                retryable=True,
            )

from __future__ import annotations

"""Standalone Langflow 1.11 client for the bounded catalog worker service."""

import json
import re
import urllib.error
import urllib.request
from typing import Any
from urllib.parse import urlsplit

from lfx.custom import Component
from lfx.io import DataInput, IntInput, MessageTextInput, Output, SecretStrInput, StrInput
from lfx.schema import Data


_IDENTIFIER = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:@-]{0,127}$")
_JOB_REF_KEYS = ("tenant_id", "job_id", "snapshot_id", "stage", "expected_cursor", "trace_id")


class _NoRedirectHandler(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req: Any, fp: Any, code: int, msg: str, headers: Any, newurl: str) -> None:
        raise urllib.error.HTTPError(req.full_url, code, "Redirects are forbidden", headers, fp)


def _secret(value: Any) -> str:
    getter = getattr(value, "get_secret_value", None)
    return str(getter() if callable(getter) else value or "").strip()


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return dict(value)
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return dict(data)
    if isinstance(value, str):
        parsed = json.loads(value)
        return dict(parsed) if isinstance(parsed, dict) else {}
    return {}


def _bounded_int(value: Any, default: int, minimum: int, maximum: int) -> int:
    try:
        number = int(value)
    except (TypeError, ValueError):
        number = default
    return max(minimum, min(maximum, number))


def _validate_job_ref(value: Any) -> dict[str, Any]:
    source = _payload(value)
    result = {key: source.get(key) for key in _JOB_REF_KEYS}
    for key in ("tenant_id", "job_id", "snapshot_id", "stage", "trace_id"):
        cleaned = str(result.get(key) or "").strip()
        if not _IDENTIFIER.fullmatch(cleaned):
            raise ValueError(f"job_ref.{key} is invalid")
        result[key] = cleaned
    try:
        result["expected_cursor"] = max(0, int(result.get("expected_cursor") or 0))
    except (TypeError, ValueError) as exc:
        raise ValueError("job_ref.expected_cursor must be an integer") from exc
    return result


def _approved_hosts(value: Any) -> set[str]:
    hosts = {item.strip().lower() for item in str(value or "").split(",") if item.strip()}
    if not hosts or any("/" in item or "@" in item for item in hosts):
        raise ValueError("approved_server_hosts must contain exact hostname or hostname:port entries")
    return hosts


def _validate_server_url(value: str, approved: set[str]) -> str:
    parsed = urlsplit(value.strip())
    hostname = (parsed.hostname or "").lower()
    host_port = f"{hostname}:{parsed.port}" if parsed.port else hostname
    loopback = hostname in {"localhost", "127.0.0.1", "::1"}
    if not hostname or parsed.username or parsed.password or parsed.query or parsed.fragment:
        raise ValueError("worker_server_url must be an absolute URL without credentials, query, or fragment")
    if parsed.scheme != "https" and not (parsed.scheme == "http" and loopback):
        raise ValueError("worker_server_url must use HTTPS outside loopback development")
    if hostname not in approved and host_port not in approved:
        raise ValueError("worker_server_url host is not in the explicit allowlist")
    return value.strip().rstrip("/")


def _failure(code: str, message: str, trace_id: str = "trace-unassigned", retryable: bool = False) -> dict[str, Any]:
    return {
        "ok": False,
        "status": "BLOCKED",
        "route": "blocked_path",
        "artifact_refs": [],
        "error": {"code": code, "message": message, "retryable": retryable, "details": {}},
        "resume": None,
        "trace_id": trace_id,
    }


def _post_json(url: str, headers: dict[str, str], payload: dict[str, Any], timeout: int, max_bytes: int) -> dict[str, Any]:
    body = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    request = urllib.request.Request(url, data=body, headers=headers, method="POST")
    opener = urllib.request.build_opener(_NoRedirectHandler())
    try:
        with opener.open(request, timeout=timeout) as response:
            content_length = response.headers.get("Content-Length")
            if content_length and int(content_length) > max_bytes:
                raise ValueError("worker response exceeds the configured byte limit")
            raw = response.read(max_bytes + 1)
            if len(raw) > max_bytes:
                raise ValueError("worker response exceeds the configured byte limit")
    except urllib.error.HTTPError as exc:
        if 300 <= exc.code < 400:
            raise ValueError("worker redirects are forbidden") from exc
        if 400 <= exc.code < 500 and exc.code not in {408, 409, 429}:
            raise ValueError(f"worker rejected a non-retryable request with HTTP {exc.code}") from exc
        raise RuntimeError(f"worker rejected the request with HTTP {exc.code}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError("worker request could not be completed") from exc
    decoded = json.loads(raw.decode("utf-8"))
    if not isinstance(decoded, dict):
        raise ValueError("worker response must be a JSON object")
    return decoded


class CatalogPipelineWorkerClientComponent(Component):
    display_name = "Catalog Pipeline Worker Client"
    description = "Run standalone catalog stages through a bounded companion worker and route only validated snapshots onward."
    icon = "Workflow"
    name = "CatalogPipelineWorkerClient"

    inputs = [
        DataInput(name="scanned_job_ref", display_name="Scanned Job Reference", required=True),
        StrInput(name="worker_server_url", display_name="Catalog Worker Base URL", value="http://127.0.0.1:8092/api", required=True),
        StrInput(
            name="approved_server_hosts",
            display_name="Approved Worker Hosts",
            value="127.0.0.1:8092,localhost:8092",
            required=True,
            advanced=True,
        ),
        SecretStrInput(name="worker_bearer_token", display_name="Catalog Worker Bearer Token", required=True),
        StrInput(name="tenant_id", display_name="Tenant ID", required=True),
        StrInput(name="actor_id", display_name="Actor ID", required=True),
        IntInput(name="max_stage_invocations", display_name="Maximum Stage Invocations", value=400, advanced=True),
        IntInput(name="request_timeout_seconds", display_name="Whole Worker Request Timeout", value=1800, advanced=True),
        IntInput(name="max_response_mb", display_name="Maximum Worker Response MiB", value=4, advanced=True),
    ]
    outputs = [
        Output(name="activation_path", display_name="Validated for Approval", method="route_result", types=["Data"], group_outputs=True),
        Output(name="blocked_path", display_name="Blocked or Incomplete", method="route_result", types=["Data"], group_outputs=True),
    ]

    def route_result(self) -> Data:
        cached = getattr(self, "_worker_result", None)
        if not isinstance(cached, dict):
            trace_id = "trace-unassigned"
            try:
                incoming = _validate_job_ref(getattr(self, "scanned_job_ref", None))
                trace_id = incoming["trace_id"]
                tenant_id = str(getattr(self, "tenant_id", "") or "").strip()
                actor_id = str(getattr(self, "actor_id", "") or "").strip()
                token = _secret(getattr(self, "worker_bearer_token", ""))
                if not _IDENTIFIER.fullmatch(tenant_id) or tenant_id != incoming["tenant_id"]:
                    raise ValueError("tenant_id must match scanned_job_ref.tenant_id")
                if not _IDENTIFIER.fullmatch(actor_id) or not token:
                    raise ValueError("actor_id and worker_bearer_token are required")
                base = _validate_server_url(
                    str(getattr(self, "worker_server_url", "") or ""),
                    _approved_hosts(getattr(self, "approved_server_hosts", "")),
                )
                timeout = _bounded_int(getattr(self, "request_timeout_seconds", 1800), 1800, 5, 7200)
                max_bytes = _bounded_int(getattr(self, "max_response_mb", 4), 4, 1, 16) * 1024 * 1024
                result = _post_json(
                    base + "/catalog/pipeline/run",
                    {
                        "Authorization": f"Bearer {token}",
                        "X-Tenant-ID": tenant_id,
                        "X-Actor-ID": actor_id,
                        "Content-Type": "application/json",
                    },
                    {
                        "job_ref": incoming,
                        "max_stage_invocations": _bounded_int(getattr(self, "max_stage_invocations", 400), 400, 1, 1000),
                    },
                    timeout,
                    max_bytes,
                )
                route = "activation_path" if result.get("ok") is True and result.get("status") == "VALIDATED" else "blocked_path"
                result = dict(result)
                result["route"] = route
                cached = result
            except ValueError as exc:
                cached = _failure("CATALOG_WORKER_CLIENT_INPUT_INVALID", str(exc), trace_id)
            except (RuntimeError, json.JSONDecodeError, UnicodeError):
                cached = _failure(
                    "CATALOG_WORKER_UNAVAILABLE",
                    "The bounded catalog worker did not return a trusted response.",
                    trace_id,
                    retryable=True,
                )
            self._worker_result = cached
        selected = str(cached.get("route") or "blocked_path")
        for output_name in ("activation_path", "blocked_path"):
            if output_name != selected:
                self.stop(output_name)
        self.status = {"ok": cached.get("ok"), "status": cached.get("status"), "route": selected}
        return Data(data=dict(cached))

"""Human Input node: pause a flow for a human decision, then route on the pick (LE-1449).

The User Choices picker chooses which actions the human can take (presets like
Approve/Reject/Escalate, or custom); each becomes a branch output. On first execution
the node requests a pause carrying a ``node_input`` request; on resume the injected
decision selects exactly one branch (the others are stopped). With Enable Fallback on,
a ``fallback`` branch is added for when no user action is answered (e.g. after timeout).
"""

from __future__ import annotations

from datetime import datetime, timezone
from typing import Any

from lfx.custom import Component
from lfx.inputs.inputs import ActionPickerInput, BoolInput, DurationInput
from lfx.io import MultilineInput, Output
from lfx.schema.message import Message

HUMAN_INPUT_REQUIRED = "human_input_required"
_KIND_NODE_INPUT = "node_input"
_FALLBACK_ACTION = "fallback"
_UNIT_SECONDS = {"Minutes": 60, "Hours": 3600, "Days": 86400}


def _action_id(label: str) -> str:
    """Stable branch id for a human-facing action label (e.g. 'Request Changes' -> 'request_changes')."""
    return str(label).strip().lower().replace(" ", "_")


class HumanInput(Component):
    display_name = "Human Input"
    description = "Pause the flow for a human-in-the-loop (HITL) decision and route on the chosen action."
    icon = "HumanInput"
    name = "HumanInput"
    metadata = {"keywords": ["hitl", "human-in-the-loop", "decision"]}

    inputs = [
        MultilineInput(
            name="prompt",
            display_name="Input",
            info="Content shown to the human for review.",
            value="",
        ),
        ActionPickerInput(
            name="decisions",
            display_name="User Choices",
            info="Choices the human can pick; each becomes a branch output. Pick from the list or type a custom one.",
            value=["Approve", "Reject"],
            real_time_refresh=True,
            required=True,
        ),
        DurationInput(
            name="timeout",
            display_name="Timeout",
            info="A response received after this window is rerouted to the fallback path (when enabled) "
            "instead of the chosen action. The run stays paused until a response arrives or the "
            "server's suspended-run deadline expires it. Set to 0 to wait indefinitely.",
            options=["Minutes", "Hours", "Days"],
            value={"value": 3, "unit": "Days"},
            advanced=True,
            show=False,
        ),
        BoolInput(
            name="enable_fallback",
            display_name="Enable Fallback",
            info="Add a 'fallback' output taken when the answer arrives after the timeout window.",
            value=False,
            advanced=True,
            real_time_refresh=True,
        ),
    ]

    # Default branch outputs mirror the default ``decisions`` so a freshly dragged
    # node shows handles immediately (update_outputs only fires on a field change).
    outputs: list[Output] = [
        Output(display_name="Approve", name="branch_approve", method="route_branch", group_outputs=True),
        Output(display_name="Reject", name="branch_reject", method="route_branch", group_outputs=True),
    ]

    async def update_frontend_node(self, new_frontend_node: dict, current_frontend_node: dict) -> dict:
        """Rebuild branch outputs from the saved User Choices so loaded/refreshed flows keep their handles."""
        new_frontend_node = await super().update_frontend_node(new_frontend_node, current_frontend_node)
        template = new_frontend_node.get("template", {})
        decisions = (template.get("decisions") or {}).get("value")
        self.update_outputs(new_frontend_node, "decisions", decisions if decisions is not None else [])
        self._sync_timeout_visibility(template)
        return new_frontend_node

    @staticmethod
    def _sync_timeout_visibility(template: dict) -> None:
        """Timeout only matters when the fallback branch exists to reroute to."""
        if "timeout" in template:
            template["timeout"]["show"] = bool((template.get("enable_fallback") or {}).get("value"))

    def update_build_config(self, build_config: dict, field_value: Any, field_name: str | None = None) -> dict:
        if field_name == "enable_fallback" and "timeout" in build_config:
            build_config["timeout"]["show"] = bool(field_value)
        return build_config

    def update_outputs(self, frontend_node: dict, field_name: str, field_value: Any) -> dict:
        """One branch output per selected action (+ optional fallback) + a stable action output."""
        if field_name not in ("decisions", "enable_fallback"):
            return frontend_node
        template = frontend_node.get("template", {})

        def _other(field: str, attr_default):
            if field in template:
                return (template.get(field) or {}).get("value")
            return getattr(self, attr_default[0], attr_default[1])

        actions = field_value if field_name == "decisions" else _other("decisions", ("decisions", []))
        fallback_on = (
            field_value if field_name == "enable_fallback" else _other("enable_fallback", ("enable_fallback", False))
        )
        outputs: list[Output] = []
        seen: set[str] = set()
        for label in actions or []:
            action_id = _action_id(label)
            if not action_id or action_id in seen:
                continue
            seen.add(action_id)
            outputs.append(
                Output(
                    display_name=str(label).strip(),
                    name=f"branch_{action_id}",
                    method="route_branch",
                    group_outputs=True,
                )
            )
        if fallback_on:
            outputs.append(
                Output(
                    display_name="Fallback",
                    name=f"branch_{_FALLBACK_ACTION}",
                    method="route_branch",
                    group_outputs=True,
                )
            )
        frontend_node["outputs"] = outputs
        return frontend_node

    def _actions(self) -> list[tuple[str, str]]:
        """Selected actions as (action_id, label) pairs, de-duplicated by id."""
        seen: set[str] = set()
        actions: list[tuple[str, str]] = []
        for label in getattr(self, "decisions", []) or []:
            action_id = _action_id(label)
            if not action_id or action_id in seen:
                continue
            seen.add(action_id)
            actions.append((action_id, str(label).strip()))
        return actions

    def _rendered_prompt(self) -> str:
        return str(getattr(self, "prompt", "") or "")

    def _timeout_seconds(self) -> int:
        timeout = getattr(self, "timeout", None) or {}
        if not isinstance(timeout, dict):
            return 0
        unit = timeout.get("unit", "Days") or "Days"
        return int(timeout.get("value", 0) or 0) * _UNIT_SECONDS.get(unit, _UNIT_SECONDS["Days"])

    def _request_id(self) -> str:
        run_id = str(getattr(self.graph, "run_id", "") or "")
        return f"{self._id}:{run_id}"

    def _injected_decision(self) -> dict | None:
        decisions = getattr(self.graph, "human_input_decisions", None) if self.graph is not None else None
        if not isinstance(decisions, dict):
            return None
        return decisions.get(self._request_id())

    def _allowed_decisions(self) -> list[str]:
        ids = [action_id for action_id, _ in self._actions()]
        if getattr(self, "enable_fallback", False):
            ids.append(_FALLBACK_ACTION)
        return ids

    def _pause_request(self) -> dict[str, Any]:
        return {
            "request_id": self._request_id(),
            "kind": _KIND_NODE_INPUT,
            "prompt": self._rendered_prompt(),
            "options": [{"action_id": action_id, "label": label} for action_id, label in self._actions()],
            "allowed_decisions": self._allowed_decisions(),
            "timeout_seconds": self._timeout_seconds(),
            "fallback_action": _FALLBACK_ACTION if getattr(self, "enable_fallback", False) else None,
            "paused_at": datetime.now(timezone.utc).isoformat(),
        }

    def _has_downstream_consumer(self) -> bool:
        """True if any branch output feeds a downstream node.

        A node with no outgoing edges runs as an isolated start vertex; pausing it would
        suspend the whole run for a decision that routes nowhere (and, alongside an Agent's
        own tool-approval pause, leave that pause unresolved on resume). The successor_map is
        absent only outside a prepared graph (standalone/tests), where the old behavior holds.
        """
        graph = getattr(self, "graph", None)
        successor_map = getattr(graph, "successor_map", None)
        if not isinstance(successor_map, dict):
            return True
        return bool(successor_map.get(self._id))

    def _suspend(self) -> None:
        self.graph.request_pause(reason=HUMAN_INPUT_REQUIRED, data=self._pause_request())
        self.status = "Awaiting human input"

    def route_branch(self) -> Message:
        decision = self._injected_decision()
        if decision is None:
            if not self._has_downstream_consumer():
                self.status = "Skipped: no connected outputs"
                return Message(text=self._rendered_prompt())
            self._suspend()
            return Message(text="")
        chosen = decision.get("action_id")
        non_chosen = [action_id for action_id in self._allowed_decisions() if action_id != chosen]
        for action_id in non_chosen:
            self.stop(f"branch_{action_id}")
        return Message(text=self._rendered_prompt())

